ALTER TABLE public.ordens_servico ADD COLUMN assinatura_entrega_path text, ADD COLUMN data_assinatura_entrega timestamptz;
CREATE POLICY "Company members read delivery signatures" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'delivery-signatures' AND EXISTS (SELECT 1 FROM public.ordens_servico o WHERE o.empresa_id::text = (storage.foldername(name))[1] AND o.id::text = (storage.foldername(name))[2] AND public.user_belongs_to_empresa(o.empresa_id)));
CREATE POLICY "Company members upload delivery signatures" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'delivery-signatures' AND EXISTS (SELECT 1 FROM public.ordens_servico o WHERE o.empresa_id::text = (storage.foldername(name))[1] AND o.id::text = (storage.foldername(name))[2] AND public.user_belongs_to_empresa(o.empresa_id)));
CREATE POLICY "Company members remove delivery signatures" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'delivery-signatures' AND EXISTS (SELECT 1 FROM public.ordens_servico o WHERE o.empresa_id::text = (storage.foldername(name))[1] AND o.id::text = (storage.foldername(name))[2] AND public.user_belongs_to_empresa(o.empresa_id)));